INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(1353770, 'Valhalla, Hall of the Fallen', '神之居城-瓦尔哈拉', '神の居城－ヴァルハラ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，自己主要阶段才能发动。从手卡把1只天使族怪兽特殊召唤。这个效果在自己场上没有怪兽存在的场合才能发动和处理。'),
(23672629, 'Valiant Shark Lancer', '瓦利安猛鲨枪兵', 'ヴァリアント・シャーク・ランサー', 'XYZ Monster', 'Beast-Warrior', 'WATER', 5, 2500, 1600, '5星怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：以对方场上1只怪兽为对象才能发动。自己场上1个超量素材取除，作为对象的怪兽破坏。自己场上有其他的水属性超量怪兽存在的场合，这个效果在对方回合也能发动。 ②：这张卡已在怪兽区域存在的状态，自己场上的其他的水属性超量怪兽被战斗·效果破坏的场合才能发动。从卡组选1张魔法卡在卡组最上面放置。'),
(99348756, 'Valkyrian Knight', '女武神骑士', 'バルキリー・ナイト', 'Effect Monster', 'Warrior', 'FIRE', 4, 1900, 1200, '①：只要这张卡在怪兽区域存在，对方不能选择「女武神骑士」以外的战士族怪兽作为攻击对象。 ②：这张卡被战斗破坏送去墓地时，从自己墓地把1只战士族怪兽和这张卡除外，以自己墓地1只5星以上的战士族怪兽为对象才能发动。那只战士族怪兽特殊召唤。'),
(2204038, 'Valkyrie Brunhilde', '女武神·布伦希尔德', 'ワルキューレ・ヴリュンヒルデ', 'Effect Monster', 'Fairy', 'LIGHT', 7, 1800, 2000, '①：这张卡的攻击力上升对方场上的怪兽数量×500。 ②：这张卡不受对方的魔法卡的效果影响。 ③：对方怪兽的攻击宣言时才能发动。这张卡的守备力下降1000，这个回合，自己的「女武神」怪兽不会被战斗破坏。'),
(19190082, 'Valkyrie Chariot', '女武神的战车', '戦乙女の戦車', 'Union Effect Monster', 'Fairy', 'WIND', 3, 500, 1000, '①：1回合1次，可以从以下效果选择1个发动。 ●以自己场上1只天使族怪兽为对象，把这张卡当作装备卡使用给那只怪兽装备。装备怪兽被战斗·效果破坏的场合，作为代替把这张卡破坏。 ●装备的这张卡特殊召唤。 ②：装备怪兽的攻击宣言时才能发动。装备怪兽的攻击力上升500。'),
(3026686, 'Valkyrie Dritte', '女武神三女', 'ワルキューレ・ドリット', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1000, 1600, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把「女武神三女」以外的1张「女武神」卡加入手卡。 ②：这张卡的攻击力上升除外的对方怪兽数量×200。'),
(83705073, 'Valkyrie Erda', '女武神·埃尔达', 'ワルキューレ・エルダ', 'Effect Monster', 'Fairy', 'LIGHT', 8, 2000, 2200, '①：「女武神·埃尔达」在自己场上只能有1只表侧表示存在。 ②：只要「女武神」卡的效果特殊召唤的这张卡在怪兽区域存在，对方场上的怪兽的攻击力下降1000。 ③：只要这张卡在怪兽区域存在，被战斗·效果破坏送去对方墓地的卡不去墓地而除外。'),
(66809920, 'Valkyrie Erste', '女武神长女', 'ワルキューレ・アルテスト', 'Effect Monster', 'Fairy', 'LIGHT', 6, 1600, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡用魔法卡的效果从手卡特殊召唤成功的场合，以自己墓地1张「时间女神的恶作剧」为对象才能发动。那张卡加入手卡。 ②：自己场上有「女武神长女」以外的「女武神」怪兽存在的场合才能发动。从对方墓地选1只怪兽除外。那之后，这张卡的攻击力直到回合结束时变成和除外的怪兽的原本攻击力相同。这个效果在对方回合也能发动。'),
(46701379, 'Valkyrie Funfte', '女武神五女', 'ワルキューレ・フュンフト', 'Effect Monster', 'Fairy', 'LIGHT', 2, 800, 1200, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上的「女武神」怪兽的攻击力上升除外的对方怪兽数量×200。 ②：自己场上有「女武神五女」以外的「女武神」怪兽存在的场合才能发动。从卡组把1张魔法·陷阱卡送去墓地。'),
(40844552, 'Valkyrie of the Nordic Ascendant', '极星天 女武神', '極星天ヴァルキュリア', 'Tuner Monster', 'Fairy', 'LIGHT', 2, 400, 800, '①：这张卡召唤成功时，对方场上有怪兽存在，自己场上没有这张卡以外的卡存在的场合，从手卡把2只「极星」怪兽除外才能发动。在自己场上把2只「英灵衍生物」（战士族·地·4星·攻/守1000）守备表示特殊召唤。'),
(44163252, 'Valkyrie Sechste', '女武神六女', 'ワルキューレ・セクスト', 'Effect Monster', 'Fairy', 'LIGHT', 1, NULL, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合才能发动。从卡组把「女武神六女」以外的1只「女武神」怪兽特殊召唤。 ②：自己主要阶段才能发动。从对方卡组上面把2张卡送去墓地。'),
(97854941, 'Valkyrie Sigrun', '女武神·希格露恩', 'ワルキューレ・シグルーン', 'Effect Monster', 'Fairy', 'LIGHT', 9, 2200, 2400, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合，以自己场上1张表侧表示的魔法·陷阱卡为对象才能发动。那张卡送去墓地，这张卡特殊召唤。 ②：这张卡召唤·特殊召唤成功的场合才能发动。从自己的手卡·墓地选1只8星以下的「女武神」怪兽特殊召唤。'),
(81558967, 'Valkyrie Vierte', '女武神四女', 'ワルキューレ・フィアット', 'Effect Monster', 'Fairy', 'LIGHT', 3, 1400, 1400, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。把这张卡以外的自己场上的「女武神」怪兽数量的卡从自己卡组上面翻开。那之中有通常魔法·通常陷阱卡的场合，选那之内的1张加入手卡，剩下的卡全部送去墓地。没有的场合，翻开的卡全部回到卡组。 ②：这张卡被战斗破坏送去墓地时才能发动。从卡组把1只「女武神」怪兽特殊召唤。'),
(30411385, 'Valkyrie Zweite', '女武神次女', 'ワルキューレ・ツヴァイト', 'Effect Monster', 'Fairy', 'LIGHT', 5, 1600, 1600, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·反转召唤·特殊召唤成功的场合，以对方场上1只怪兽为对象才能发动。那只怪兽破坏。 ②：这张卡进行战斗的伤害计算后，以自己墓地1张永续魔法卡为对象才能发动。那张卡加入手卡。'),
(45584727, 'Valkyrie''s Embrace', '女武神的拥抱', 'ワルキューレの抱擁', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不是「女武神」怪兽不能特殊召唤。 ①：自己场上的怪兽只有「女武神」怪兽的场合，以自己场上1只攻击表示的「女武神」怪兽和对方场上1只表侧表示怪兽为对象才能发动。那只自己怪兽变成守备表示，那只对方怪兽除外。'),
(75347539, 'Valkyrion the Magna Warrior', '磁石之战士 翔武机翁', '磁石の戦士マグネット・バルキリオン', 'Effect Monster', 'Rock', 'EARTH', 8, 3500, 3850, '这张卡不能通常召唤。从自己的手卡·场上把「磁石战士α」「磁石战士β」「磁石战士γ」各1只解放的场合可以特殊召唤。 ①：把这张卡解放，以自己墓地的「磁石战士α」「磁石战士β」「磁石战士γ」各1只为对象才能发动。那些怪兽特殊召唤。'),
(40673853, 'Vallon, the Super Psy Skyblaster', '超念铳士瓦隆', '超念銃士ヴァロン', 'XYZ Monster', 'Psychic', 'DARK', 5, 2500, 2200, '5星怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，把这张卡1个超量素材取除，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽变成里侧守备表示。 ②：这张卡被送去墓地的场合，以场上1张里侧表示卡为对象才能发动。那张卡破坏。'),
(31189536, 'Vampire Awakening', '吸血鬼觉醒', 'ヴァンパイア・アウェイク', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把1只「吸血鬼」怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合的结束阶段破坏。'),
(56387350, 'Vampire Baby', '吸血鬼婴儿', 'ヴァンパイア・ベビー', 'Effect Monster', 'Zombie', 'DARK', 3, 700, 1000, '这张卡战斗破坏怪兽的战斗阶段结束时，可以把墓地存在的那些怪兽在自己场上特殊召唤。'),
(68688135, 'Vampire Domination', '吸血鬼的支配', 'ヴァンパイアの支配', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「吸血鬼」怪兽存在，怪兽的效果·魔法·陷阱卡发动时才能发动。那个发动无效并破坏。那之后，破坏的卡是怪兽卡的场合，自己回复那个原本攻击力数值的基本分。'),
(36352429, 'Vampire Dragon', '吸血鬼龙', 'ヴァンパイア・ドラゴン', 'Effect Monster', 'Zombie', 'DARK', 5, 2400, NULL, '上级召唤的这张卡从场上送去墓地时，可以从卡组把1只4星以下的怪兽加入手卡。'),
(58947797, 'Vampire Duke', '吸血鬼公爵', 'ヴァンパイア・デューク', 'Effect Monster', 'Zombie', 'DARK', 5, 2000, NULL, '「吸血鬼公爵」的②的效果1回合只能使用1次。把这张卡作为超量召唤的素材的场合，不是暗属性怪兽的超量召唤不能使用。 ①：这张卡召唤成功时，以自己墓地1只暗属性「吸血鬼」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。 ②：这张卡特殊召唤成功时，宣言卡的种类（怪兽·魔法·陷阱）才能发动。对方把宣言的种类的1张卡从卡组送去墓地。'),
(34250214, 'Vampire Familiar', '吸血鬼的使役魔', 'ヴァンパイアの使い魔', 'Effect Monster', 'Zombie', 'DARK', 1, 500, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合，支付500基本分才能发动。从卡组把「吸血鬼的使魔」以外的1只「吸血鬼」怪兽加入手卡。 ②：这张卡在墓地存在的场合，从手卡以及自己场上的表侧表示的卡之中把1张「吸血鬼」卡送去墓地才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(72860663, 'Vampire Fascinator', '吸血鬼魅惑者', 'ヴァンパイア・ファシネイター', 'Link Monster', 'Zombie', 'DARK', NULL, 2400, NULL, '包含不死族怪兽的怪兽2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡连接召唤成功的场合，以对方墓地1只怪兽为对象才能发动。那只怪兽在自己场上守备表示特殊召唤。这个回合，自己不是不死族怪兽不能特殊召唤。 ②：把自己场上1只「吸血鬼」怪兽解放，以对方场上1只怪兽为对象才能发动。那只怪兽的控制权直到结束阶段得到。'),
(6039967, 'Vampire Fraulein', '吸血鬼大小姐', 'ヴァンパイア・フロイライン', 'Effect Monster', 'Zombie', 'DARK', 5, 600, 2000, '这个卡名的①的效果1回合只能使用1次。 ①：怪兽的攻击宣言时才能发动。这张卡从手卡守备表示特殊召唤。 ②：自己的不死族怪兽和对方怪兽进行战斗的伤害计算时1次，支付100的倍数的基本分才能发动（最多3000）。那只自己怪兽的攻击力·守备力只在那次伤害计算时上升支付的数值。 ③：这张卡战斗破坏怪兽的战斗阶段结束时才能发动。那些怪兽从墓地尽可能往自己场上特殊召唤。'),
(22056710, 'Vampire Genesis', '吸血鬼创世主', 'ヴァンパイアジェネシス', 'Effect Monster', 'Zombie', 'DARK', 8, 3000, 2100, '这张卡不能通常召唤。把自己场上存在的1只「吸血鬼领主」从游戏中除外的场合才能特殊召唤。1回合1次，可以通过从手卡把1只不死族怪兽丢弃去墓地，从自己墓地选择1只比丢弃的不死族怪兽等级低的不死族怪兽特殊召唤。'),
(90299015, 'Vampire Ghost', '吸血鬼的幽鬼', 'ヴァンパイアの幽鬼', 'Effect Monster', 'Zombie', 'DARK', 3, 1500, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤成功的场合，从手卡以及自己场上的表侧表示的卡之中把这张卡以外的1张「吸血鬼」卡送去墓地才能发动。从卡组把1只4星以上的「吸血鬼」怪兽加入手卡，从卡组把1只2星以下的「吸血鬼」怪兽送去墓地。 ②：自己·对方的主要阶段，把墓地的这张卡除外，支付500基本分才能发动。把1只「吸血鬼」怪兽召唤。'),
(40607210, 'Vampire Grace', '吸血鬼女王', 'ヴァンパイア・グレイス', 'Effect Monster', 'Zombie', 'DARK', 6, 2000, 1200, '这张卡在墓地存在，不死族怪兽的效果让自己场上有5星以上的不死族怪兽特殊召唤时，支付2000基本分才能发动。这张卡从墓地特殊召唤。「吸血鬼·格蕾丝」的这个效果1回合只能使用1次。此外，1回合1次，宣言卡的种类（怪兽·魔法·陷阱）才能发动。对方把宣言的种类的1张卡从卡组送去墓地。'),
(33438666, 'Vampire Grimson', '吸血鬼绯红死神', 'ヴァンパイア・グリムゾン', 'Effect Monster', 'Zombie', 'DARK', 5, 2000, 1400, '①：自己场上的怪兽被战斗或者对方的效果破坏的场合，可以作为代替而支付那些破坏的怪兽数量×1000基本分。 ②：这张卡战斗破坏怪兽的战斗阶段结束时才能发动。那些怪兽从墓地尽可能往自己场上特殊召唤。'),
(80485722, 'Vampire Hunter', '吸血鬼杀手', 'ヴァンパイア・キラー', 'Effect Monster', 'Warrior', 'DARK', 4, 1600, 1600, '这张卡和暗属性怪兽进行战斗的场合，不进行伤害计算把那只怪兽破坏。'),
(62188962, 'Vampire Kingdom', '吸血鬼帝国', 'ヴァンパイア帝国', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '场上的不死族怪兽的攻击力只在伤害计算时上升500。此外，1回合1次，从对方卡组有卡被送去墓地时，从自己的手卡·卡组把1只名字带有「吸血鬼」的暗属性怪兽送去墓地，选择场上1张卡破坏。'),
(26495087, 'Vampire Lady', '吸血鬼女郎', 'ヴァンパイア・レディ', 'Effect Monster', 'Zombie', 'DARK', 4, 1550, 1550, '每当这张卡对对方造成战斗伤害时，宣言1个卡的种类（怪兽·魔法·陷阱），对方从其卡组中选择1张此种类的卡送去墓地。'),
(53839837, 'Vampire Lord', '吸血鬼领主', 'ヴァンパイア・ロード', 'Effect Monster', 'Zombie', 'DARK', 5, 2000, 1500, '①：这张卡给与对方战斗伤害的场合，宣言1个卡的种类（怪兽·魔法·陷阱）发动。对方把宣言的种类的1张卡从自身卡组送去墓地。 ②：这张卡被对方的效果破坏送去墓地的场合，下次的自己准备阶段发动。这张卡从墓地特殊召唤。'),
(6917479, 'Vampire Red Baron', '吸血鬼红男爵', 'ヴァンパイア・レッドバロン', 'Effect Monster', 'Zombie', 'DARK', 6, 2400, 1000, '①：1回合1次，支付1000基本分，以对方场上1只怪兽和这张卡以外的自己场上1只「吸血鬼」怪兽为对象才能发动。那2只怪兽的控制权交换。 ②：这张卡战斗破坏怪兽的战斗阶段结束时才能发动。那些怪兽从墓地尽可能往自己场上特殊召唤。'),
(70645913, 'Vampire Retainer', '吸血鬼的眷属', 'ヴァンパイアの眷属', 'Effect Monster', 'Zombie', 'DARK', 2, 1200, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合，支付500基本分才能发动。从卡组把1张「吸血鬼」魔法·陷阱卡加入手卡。 ②：这张卡在墓地存在的场合，从手卡以及自己场上的表侧表示的卡之中把1张「吸血鬼」卡送去墓地才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(79523365, 'Vampire Scarlet Scourge', '吸血鬼猩红灾星', 'ヴァンパイア・スカージレット', 'Effect Monster', 'Zombie', 'DARK', 6, 2200, 2200, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合，支付1000基本分，以「吸血鬼·红灾星」以外的自己墓地1只「吸血鬼」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合不能攻击。 ②：这张卡战斗破坏怪兽的战斗阶段结束时才能发动。那些怪兽从墓地尽可能往自己场上特殊召唤。'),
(88728507, 'Vampire Sorcerer', '吸血鬼巫师', 'ヴァンパイア・ソーサラー', 'Effect Monster', 'Zombie', 'DARK', 4, 1500, 1500, '①：这张卡被对方送去墓地的场合才能发动。从卡组把1只暗属性「吸血鬼」怪兽或者1张「吸血鬼」魔法·陷阱卡加入手卡。 ②：把墓地的这张卡除外才能发动。这个回合只有1次，自己在5星以上的暗属性「吸血鬼」怪兽召唤的场合需要的解放可以不用。'),
(37129797, 'Vampire Sucker', '吸血鬼吸食者', 'ヴァンパイア・サッカー', 'Link Monster', 'Zombie', 'DARK', NULL, 1600, NULL, '不死族怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：以对方墓地1只怪兽为对象才能发动。那只怪兽在对方场上守备表示特殊召唤。这个效果特殊召唤的怪兽变成不死族。 ②：从自己·对方的墓地有不死族怪兽特殊召唤的场合发动。自己抽1张。 ③：自己把怪兽上级召唤的场合，可以作为自己场上的怪兽的代替而把对方场上的不死族怪兽解放。'),
(22900598, 'Vampire Takeover', '吸血鬼移地', 'ヴァンパイア・シフト', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己的场地卡区域没有卡存在，自己场上表侧表示存在的怪兽只有不死族怪兽的场合才能发动。从卡组选1张「吸血鬼帝国」发动。那之后，可以从自己墓地选1只名字带有「吸血鬼」的暗属性怪兽表侧守备表示特殊召唤。「吸血鬼移地」在1回合只能发动1张。'),
(82962242, 'Vampire Vamp', '吸血鬼妖女', 'ヴァンプ・オブ・ヴァンパイア', 'Effect Monster', 'Zombie', 'DARK', 7, 2000, 2000, '①：这张卡召唤成功时或者自己场上有「吸血鬼」怪兽召唤时，以比这张卡攻击力高的对方场上1只怪兽为对象才能发动。那只怪兽当作装备卡使用给这张卡装备。这个效果1回合只能使用1次。 ②：这张卡的攻击力上升这张卡的效果装备的怪兽的原本攻击力数值。 ③：用这张卡的效果把装备卡装备的这张卡被送去墓地的场合发动。这张卡从墓地特殊召唤。'),
(4918855, 'Vampire Voivode', '龙血公 吸血鬼', '竜血公ヴァンパイア', 'Effect Monster', 'Zombie', 'DARK', 8, 2800, 2100, '这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡召唤成功的场合，以对方墓地最多2只怪兽为对象才能发动。那些怪兽效果无效在自己场上守备表示特殊召唤。 ②：怪兽的效果发动时，那些同名怪兽在自己·对方的墓地存在的场合才能发动。那个发动无效。 ③：从对方墓地有怪兽特殊召唤的场合，把自己场上2只怪兽解放才能发动。这张卡从墓地特殊召唤。'),
(34294855, 'Vampire''s Curse', '诅咒之吸血鬼', 'カース・オブ・ヴァンパイア', 'Effect Monster', 'Zombie', 'DARK', 6, 2000, 800, '这张卡被战斗破坏送去墓地时，支付500基本分才能发动。下个回合的准备阶段时，这张卡从墓地特殊召唤。此外，这个效果特殊召唤成功时发动。这张卡的攻击力上升500。'),
(69700783, 'Vampire''s Desire', '吸血鬼欲望', 'ヴァンパイア・デザイア', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。 ●以自己场上1只表侧表示怪兽为对象才能发动。把持有和那只怪兽的等级不同等级的1只「吸血鬼」怪兽从卡组送去墓地。作为对象的怪兽的等级直到回合结束时变成和送去墓地的怪兽相同。 ●以自己墓地1只「吸血鬼」怪兽为对象才能发动。选自己场上1只怪兽送去墓地，作为对象的怪兽特殊召唤。'),
(5795882, 'Vampire''s Domain', '吸血鬼的领域', 'ヴァンパイアの領域', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，支付500基本分才能发动。这个回合自己在通常召唤外加上只有1次，自己主要阶段可以把1只「吸血鬼」怪兽召唤。 ②：只要这张卡在魔法与陷阱区域存在，自己的「吸血鬼」怪兽给与对方战斗伤害的场合发动。自己基本分回复那个数值。'),
(300302074, 'Vampiric Aristocracy', NULL, NULL, 'Skill Card', 'Camula', NULL, NULL, NULL, NULL, NULL),
(1371589, 'Vampiric Koala', '吸血树熊', '吸血コアラ', 'Effect Monster', 'Beast', 'EARTH', 4, 1800, 1500, '这张卡和怪兽的战斗给与对方基本分战斗伤害时，自己基本分回复给与的战斗伤害的数值。'),
(46571052, 'Vampiric Orchis', '血兰', 'ブラッド・オーキス', 'Effect Monster', 'Plant', 'EARTH', 4, 1700, 1000, '这张卡召唤成功时，可以从手卡特殊召唤1只「死亡石斛」。'),
(24857466, 'Van''Dalgyon the Dark Dragon Lord', '冥王龙 断罪神', '冥王竜ヴァンダルギオン', 'Effect Monster', 'Dragon', 'DARK', 8, 2800, 2500, '对方控制的卡的发动用反击陷阱无效的场合，这张卡可以从手卡特殊召唤。这个方法特殊召唤成功时，把无效的卡种类的以下效果发动。 ●魔法：给与对方基本分1500分伤害。 ●陷阱：选择对方场上1张卡破坏。 ●效果怪兽：从自己墓地选择1只怪兽在自己场上特殊召唤。'),
(61777313, 'Vanadis of the Nordic Ascendant', '极星天 凡娜迪丝', '極星天ヴァナディース', 'Tuner Monster', 'Fairy', 'DARK', 4, 1200, 400, '这张卡可以作为「极星」调整的代替而成为同调素材。把这张卡作为同调素材的场合，其他的同调素材怪兽必须全部是「极星」怪兽。 ①：1回合1次，把持有和这张卡的等级不同等级的1只「极星」怪兽从卡组送去墓地才能发动。这张卡的等级直到回合结束时变成和送去墓地的怪兽相同。'),
(77135531, 'Vanguard of the Dragon', '龙之尖兵', '竜の尖兵', 'Effect Monster', 'Dragon', 'EARTH', 4, 1700, 1300, '①：从手卡把1只龙族怪兽送去墓地才能发动。这张卡的攻击力上升300。 ②：场上的这张卡被对方的效果送去墓地时，以自己或者对方的墓地1只龙族通常怪兽为对象才能发动。那只龙族怪兽特殊召唤。'),
(84366728, 'Vanguard of the Underground Emperor', '地底王的尖兵', '地底王の尖兵', 'Effect Monster', 'Reptile', 'EARTH', 8, 2600, 2200, '这个卡名的效果1回合只能使用1次。 ①：这张卡在墓地存在的状态，从自己或对方的手卡有怪兽被送去墓地的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合回到卡组最下面。'),
(24838456, 'Vanity''s Call', '呼唤虚无的咒文', '虚無を呼ぶ呪文', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '连锁4以后把基本分支付一半才能发动。这张卡的发动时积累的连锁上的全部卡的发动无效并破坏。'),
(5851097, 'Vanity''s Emptiness', '虚无空间', '虚無空間', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，双方不能把怪兽特殊召唤。 ②：从卡组或者场上有卡被送去自己墓地的场合发动。这张卡破坏。'),
(47084486, 'Vanity''s Fiend', '虚无魔者', '虚無魔人', 'Effect Monster', 'Fiend', 'DARK', 6, 2400, 1200, '这张卡不能特殊召唤。 ①：只要这张卡在怪兽区域存在，双方不能把怪兽特殊召唤。'),
(72634965, 'Vanity''s Ruler', '虚无的统括者', '虚無の統括者', 'Effect Monster', 'Fairy', 'LIGHT', 8, 2500, 1600, '这张卡不能特殊召唤。 ①：只要这张卡在怪兽区域存在，对方不能把怪兽特殊召唤。'),
(27345070, 'Vanquish Soul - Continue?', '对击斗魂 续关', 'VS コンティニュー', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：支付500基本分，以自己墓地1只「征服斗魂」怪兽为对象才能发动。那只怪兽加入手卡或守备表示特殊召唤。'),
(91073013, 'Vanquish Soul Caesar Valius', '对击斗魂 龙帝瓦里乌斯', 'VS 龍帝ヴァリウス', 'Effect Monster', 'Dragon', 'EARTH', 8, 3000, 1500, '这个卡名的①②的效果1回合各能使用1次，同一连锁上不能发动。 ①：自己·对方的主要阶段，以龙族以外的自己场上1只「征服斗魂」怪兽为对象才能发动。那只怪兽回到手卡，这张卡从手卡特殊召唤。 ②：自己·对方回合，可以从以下选择1个，把那属性的手卡的怪兽各1只给对方观看发动。 ●地：这个回合，表侧表示的这张卡不受对方发动的效果影响。 ●地·炎·暗：选场上1张其他卡破坏。'),
(80738884, 'Vanquish Soul Calamity Caesar', '对击斗魂 龙帝之枪', 'VS 龍帝ノ槍', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「征服斗魂」怪兽存在，自己场上的卡为对象的怪兽的效果·魔法·陷阱卡由对方发动时才能发动。那个发动无效并破坏。那之后，可以选自己场上1只「征服斗魂」怪兽给与对方那个攻击力数值的伤害。'),
(29280200, 'Vanquish Soul Dr. Mad Love', '对击斗魂 狂恋博士', 'VS Dr.マッドラヴ', 'Effect Monster', 'Fiend', 'DARK', 4, 1200, 2000, '这个卡名的①②的效果1回合各能使用1次，同一连锁上不能发动。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1张「征服斗魂」魔法·陷阱卡加入手卡。 ②：自己·对方回合，可以从以下选择1个，把那属性的手卡的怪兽各1只给对方观看发动。 ●暗：选对方场上1只表侧表示怪兽，那个攻击力·守备力下降500。 ●暗·地：场上1只守备力最低的怪兽回到持有者手卡。'),
(91951471, 'Vanquish Soul Dust Devil', '对击斗魂 螺旋流辻风', 'VS 螺旋流辻風', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只「征服斗魂」怪兽为对象才能发动。那只怪兽的表示形式变更。那之后，可以选最多有自己场上的「征服斗魂」怪兽种类数量的对方场上的表侧表示怪兽变成里侧守备表示。'),
(92895501, 'Vanquish Soul Heavy Borger', '对击斗魂 重型博格', 'VS ヘヴィ・ボーガー', 'Effect Monster', 'Machine', 'DARK', 7, 2500, 1500, '这个卡名的①②的效果1回合各能使用1次，同一连锁上不能发动。 ①：自己·对方的主要阶段，以机械族以外的自己场上1只「征服斗魂」怪兽为对象才能发动。那只怪兽回到手卡，这张卡从手卡特殊召唤。 ②：自己·对方回合，可以从以下选择1个，把那属性的手卡的怪兽各1只给对方观看发动。 ●暗：自己从卡组抽1张。 ●地·炎：给与对方1500伤害。'),
(93156774, 'Vanquish Soul Hollie Sue', '对击斗魂 神圣苏', 'VS ホーリー・スー', 'Effect Monster', 'Psychic', 'EARTH', 5, 500, 2200, '这个卡名的①②的效果1回合各能使用1次，同一连锁上不能发动。 ①：自己·对方的主要阶段，把手卡1只其他的「征服斗魂」怪兽给对方观看才能发动。这张卡从手卡特殊召唤。 ②：自己·对方回合，可以从以下选择1个，把那属性的手卡的怪兽各1只给对方观看发动。 ●地·暗：对方场上1只攻击力最低的怪兽的控制权直到结束阶段得到。 ●炎·暗：从卡组把1只念动力族以外的「征服斗魂」怪兽特殊召唤。'),
(9091064, 'Vanquish Soul Jiaolong', '对击斗魂 蛟龙', 'VS 蛟龍', 'Effect Monster', 'Wyrm', 'FIRE', 5, 2400, 2100, '这个卡名的①②的效果1回合各能使用1次，同一连锁上不能发动。 ①：自己为让「征服斗魂」卡的效果发动而把手卡给人观看的场合才能发动。这张卡从手卡特殊召唤。 ②：自己·对方回合，可以从以下选择1个，把那属性的手卡的怪兽各1只给对方观看发动。 ●炎：场上1只怪兽的表示形式变更。 ●炎·炎：从卡组把「征服斗魂 蛟龙」以外的1张「征服斗魂」卡加入手卡。'),
(66401502, 'Vanquish Soul Pantera', '对击斗魂 豹特拉', 'VS パンテラ', 'Effect Monster', 'Beast-Warrior', 'EARTH', 4, 1700, 1900, '这个卡名的①②的效果1回合各能使用1次，同一连锁上不能发动。 ①：自己的主要怪兽区域没有怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：自己·对方回合，可以从以下选择1个，把那属性的手卡的怪兽各1只给对方观看发动。 ●地：这个回合，这张卡不会被战斗破坏。 ●地·炎：和这张卡相同纵列的魔法·陷阱卡全部破坏。'),
(55688914, 'Vanquish Soul Pluton HG', '对击斗魂 普路托HG', 'VS プルトンHG', 'Effect Monster', 'Zombie', 'FIRE', 6, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次，同一连锁上不能发动。 ①：对方回合，自己的主要怪兽区域的怪兽不存在的场合或者只有「征服斗魂」怪兽的场合才能发动。这张卡从手卡特殊召唤。 ②：自己·对方回合，可以从以下选择1个，把那属性的手卡的怪兽各1只给对方观看发动。 ●炎：这张卡的守备力直到回合结束时上升3000。 ●暗·地：这张卡的攻击力直到回合结束时上升3000。'),
(29302858, 'Vanquish Soul Razen', '对击斗魂 螺旋', 'VS ラゼン', 'Effect Monster', 'Warrior', 'FIRE', 4, 1800, 1500, '这个卡名的①②的效果1回合各能使用1次，同一连锁上不能发动。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把1只战士族以外的「征服斗魂」怪兽加入手卡。 ②：自己·对方回合，可以从以下选择1个，把那属性的手卡的怪兽各1只给对方观看发动。 ●炎：这个回合，这张卡不会被效果破坏。 ●炎·暗：和这张卡相同纵列的其他怪兽全部破坏。'),
(77894049, 'Vanquish Soul Rocks', '对击斗魂 项', 'VS ロックス', 'XYZ Monster', 'Pyro', 'DARK', 4, 2000, 2500, '4星「征服斗魂」怪兽×2只以上 「征服斗魂 洛克斯」在「征服斗魂」怪兽进行过战斗的回合有1次也能在自己场上的「征服斗魂」怪兽或「斗神的虚像」上面重叠来超量召唤。 ①：这张卡作为超量素材中的怪兽属性让这张卡得到以下效果。 ●暗：对方场上的怪兽的攻击力下降800。 ●炎：自己场上的「征服斗魂」怪兽的攻击力上升1000。 ●地：把这张卡1个超量素材取除才能发动。对方场上1张卡破坏。'),
(60883493, 'Vanquish Soul Snow Devil', '对击斗魂 里螺旋流雪风', 'VS 裏螺旋流雪風', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把手卡的暗·地·炎属性怪兽各最多1只给对方观看才能发动。给人观看的怪兽数量的以下效果各适用。 ●1只以上：给与对方400伤害。那之后，可以从手卡把1只「征服斗魂」怪兽特殊召唤。 ●2只以上：给与对方600伤害。这个回合中，自己场上的「征服斗魂」怪兽不会被效果破坏。 ●3只：给与对方800伤害。那之后，可以把场上的怪兽全部破坏。'),
(53330789, 'Vanquish Soul Trinity Burst', '对击斗魂 三重爆裂', 'VS トリニティ・バースト', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只「征服斗魂」怪兽为对象才能发动。原本属性和那只怪兽不同的最多2只「征服斗魂」怪兽从手卡效果无效特殊召唤（同名卡最多1张）。那之后，可以让位于作为对象的自己怪兽以及这个效果特殊召唤的怪兽的正对面的对方场上的卡全部回到持有者手卡。这个效果特殊召唤的怪兽在结束阶段回到持有者手卡。'),
(35550352, 'Vanquish Soul, Start!', '对击斗魂开战！', 'Start for VS！', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①②③的效果1回合各能使用1次。 ①：以自己场上1只「征服斗魂」怪兽为对象才能发动。和那只怪兽属性不同的1只「征服斗魂」怪兽从卡组加入手卡。 ②：自己场上的「征服斗魂」怪兽被战斗·效果破坏的场合，可以作为代替把手卡1只「征服斗魂」怪兽给人观看。 ③：自己结束阶段，自己场上有「征服斗魂」怪兽2只以上存在的场合才能发动。从卡组把1张「征服斗魂」陷阱卡在自己场上盖放。'),
(32233746, 'Vanquishing Light', '光之放逐', 'ライト・バニッシュ', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '把自己场上存在的1只名字带有「光道」的怪兽解放发动。怪兽的召唤·反转召唤·特殊召唤无效并破坏。'),
(1340142, 'Varar, Vaalmonican Concord', '华耳琴璃之神奏－华岚尔', 'ヴァルモニカの神奏－ヴァーラル', 'Link Monster', 'Spellcaster', 'WATER', NULL, 3000, NULL, '包含「异响鸣」连接怪兽的怪兽2只 ①：只要自己场上有响鸣指示物6个以上存在，场上的这张卡不受「异响鸣」卡以外的卡的效果影响。 ②：这张卡在同1次的战斗阶段中在通常攻击外加上可以作出最多有自己场上的4星「异响鸣」怪兽数量的攻击。 ③：1回合1次，对方把怪兽特殊召唤之际才能发动。那次特殊召唤无效，那些怪兽破坏。那之后，自己场上3个响鸣指示物取除。'),
(19743887, 'VARefar, the Judge of Ball', '蹴神－VARefar', '蹴神－VARefar', 'Effect Monster', 'Fiend', 'EARTH', 11, 2100, 800, '这个卡名的效果1回合只能使用1次。 ①：自己场上的怪兽成为对方场上的怪兽的效果的对象时或者被选择作为对方怪兽的攻击对象时才能发动。这张卡从手卡特殊召唤。那之后，可以选那1只对方怪兽并把1张手卡给对方观看。那个场合，再让给人观看的卡种类的以下效果对选的怪兽适用。 ●怪兽：变成守备表示。 ●魔法：攻击力变成2倍。 ●陷阱：除外。'),
(64038662, 'Variable Form', '可变形态', 'ヴァリュアブル・フォーム', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '1回合1次，可以从以下效果选择1个发动。 ●选择自己场上2只名字带有「甲虫装机」的怪兽，选择的1只怪兽给另1只怪兽装备。 ●选择自己场上1只当作装备卡使用的名字带有「甲虫装机」的怪兽在自己场上表侧守备表示特殊召唤。'),
(65196094, 'Variety Comes Out', '多彩释放', 'バラエティ・アウト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '让自己场上表侧表示存在的1只同调怪兽回到额外卡组发动。直到等级合计和那只同调怪兽的等级相同，选择自己墓地存在的调整在自己场上特殊召唤。这张卡发动的回合，自己不能同调召唤。'),
(70636044, 'Varudras, the Final Bringer of the End Times', '终戒超兽－瓦鲁达罗斯', '終戒超獸－ヴァルドラス', 'XYZ Monster', 'Wyrm', 'DARK', 10, 3000, 3000, '10星怪兽×2只以上 这个卡名的①②③的效果1回合各能使用1次。 ①：对方把效果发动时，把这张卡1个超量素材取除才能发动。那个发动无效。那之后，可以把这张卡1个超量素材取除。那个场合，再把场上1张卡破坏。 ②：持有超量素材的这张卡攻击的伤害步骤开始时才能发动。场上1张卡破坏。 ③：超量召唤的这张卡被破坏的场合才能发动。场上1张卡破坏。'),
(22404676, 'Vassal Token', '雷帝家臣密斯拉', '雷帝家臣ミスラ', 'Token', 'Thunder', NULL, NULL, NULL, NULL, NULL),
(14418464, 'Vaylantz Buster Baron', '弈勇－爆破男爵', 'ヴァリアンツB－バロン', 'Pendulum Effect Monster', 'Machine', 'FIRE', 2, 800, 800, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：这张卡是已特殊召唤的场合，以这张卡以外的自己的主要怪兽区域1只「群豪」怪兽为对象才能发动。那只自己怪兽的位置向那个相邻的怪兽区域移动。 ②：怪兽区域的这张卡向其他的怪兽区域移动的场合，以自己或者对方的灵摆区域1张卡为对象才能发动。那张卡在那个相邻的魔法与陷阱区域当作永续魔法卡使用以表侧表示放置。'),
(13291886, 'Vaylantz Dominator Duke', '弈勇－支配者公爵', 'ヴァリアンツD－デューク', 'Pendulum Effect Monster', 'Machine', 'FIRE', 8, 2000, 2000, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：以魔法与陷阱区域盖放的1张卡为对象才能发动。盖放的那张卡在这个回合不能发动。 ②：怪兽区域的这张卡向其他的怪兽区域移动的场合，以对方的主要怪兽区域1只表侧表示怪兽为对象才能发动。得到那只表侧表示怪兽的控制权。这个效果得到控制权的怪兽不能攻击宣言，不能把效果发动，也当作「群豪」怪兽使用。'),
(76075139, 'Vaylantz Genesis Grand Duke', '弈勇－创世大公', 'ヴァリアンツG－グランデューク', 'Pendulum Effect Fusion Monster', 'Machine', 'FIRE', 10, 2500, 2500, '「群豪」怪兽×2 额外卡组的里侧表示的这张卡用融合召唤以及以下方法才能特殊召唤。 ●把除融合怪兽外的和额外怪兽区域相同纵列1只自己的5星以上的「群豪」怪兽解放的场合可以特殊召唤。 ①：这张卡特殊召唤成功的场合，以对方的魔法与陷阱区域1张怪兽卡为对象才能发动。那张卡回到持有者手卡，给与对方那个攻击力数值的伤害。那之后，这张卡的攻击力上升给与的伤害一半数值。'),
(87897777, 'Vaylantz Mad Marquess', '弈勇－疯狂侯爵', 'ヴァリアンツM－マーキス', 'Pendulum Effect Monster', 'Machine', 'FIRE', 6, 1700, 1700, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：自己主要阶段才能发动。掷1次骰子，把出现的数目数量的卡从自己卡组上面翻开。可以从那之中选1张「群豪」卡加入手卡。剩余回到卡组。 ②：怪兽区域的这张卡向其他的怪兽区域移动的场合才能发动。掷1次骰子，2～5出现的场合，选自己的魔法与陷阱区域1张怪兽卡在那个正对面的自己的主要怪兽区域特殊召唤。'),
(41802073, 'Vaylantz Voltage Viscount', '弈勇－伏特子爵', 'ヴァリアンツV－ヴァイカント', 'Pendulum Effect Monster', 'Machine', 'FIRE', 4, 1400, 1400, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：这张卡是已特殊召唤的场合，自己主要阶段才能发动。从自己的额外卡组选1只表侧表示的「群豪」灵摆怪兽在自己的魔法与陷阱区域当作永续魔法卡使用以表侧表示放置。 ②：怪兽区域的这张卡向其他的怪兽区域移动的场合才能发动。从自己的额外卡组选1只表侧表示的「群豪」灵摆怪兽在自己的灵摆区域放置。'),
(60095092, 'Vaylantz Wakening - Solo Activation', '弈勇觉醒－单人激活', 'VV－ソロアクティベート', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从卡组选1只「群豪」灵摆怪兽在自己的灵摆区域放置。 ②：场地区域有卡存在的场合，把墓地的这张卡除外，以自己的主要怪兽区域1只「群豪」怪兽为对象才能发动。那只自己怪兽的位置向那个相邻的怪兽区域移动。'),
(13179234, 'Vaylantz Wars - The Place of Beginning', '弈勇战争～起始之地～', 'VV～始まりの地～', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从卡组把1张「群豪」场地魔法卡加入手卡。那之后，以下效果可以适用。 ●选自己场上1张灵摆怪兽卡破坏，从卡组把1张「位置移动」加入手卡。 ②：把墓地的这张卡除外才能发动。从自己的额外卡组选1只表侧表示的「群豪」灵摆怪兽在自己的灵摆区域放置。这个效果在这张卡送去墓地的回合不能发动。'),
(84281045, 'Vaylantz Wave - Master Phase', '弈勇觉醒－大师阶段', 'VV－マスターフェイズ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，怪兽区域的卡向其他的怪兽区域移动的场合，可以从以下效果选择1个发动。 ●自己场上的全部5星以上的「群豪」怪兽的攻击力直到回合结束时上升1200。 ●把魔法与陷阱区域的表侧表示的这张卡送去墓地，以对方的主要怪兽区域1只效果怪兽为对象才能发动。那只对方怪兽在和那只是相同纵列的对方的魔法与陷阱区域当作永续魔法卡使用以表侧表示放置（所要放置区的卡破坏）。'),
(75952542, 'Vaylantz World - Konig Wissen', '弈勇世界－百识公国', 'VV－百識公国', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，从卡组把「群豪世界-百识公国」以外的1张「群豪」场地魔法卡在对方的场地区域表侧表示放置。 ②：场地区域有2张卡的场合，回合玩家以自身怪兽的正对面的对方的主要怪兽区域1只效果怪兽为对象才能发动。那只对方怪兽在相同纵列的对方的魔法与陷阱区域当作永续魔法卡使用以表侧表示放置（所要放置区的卡破坏）。'),
(49568943, 'Vaylantz World - Shinra Bansho', '弈勇世界－真罗万象', 'VV－真羅万象', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，从卡组把「群豪世界-真罗万象」以外的1张「群豪」场地魔法卡在对方的场地区域表侧表示放置。 ②：场地区域有2张卡的场合，回合玩家以自身的魔法与陷阱区域1张怪兽卡为对象才能发动。那张卡在那个正对面的自身的主要怪兽区域特殊召唤。'),
(69512157, 'Vector Pendulum, the Dracoverlord', '龙魔王 矢量主载 灵摆', '竜魔王ベクターP', 'Pendulum Normal Monster', 'Dragon', 'DARK', 4, 1850, NULL, '统率着突然出现在这个世上并转眼就彻底蹂躏了世界的大群龙魔族的魔王。据说他是以“龙化秘法”转变了万物成为邪恶的龙形，不过那种力量的真面目还不怎么清楚。强大魔力的源泉甚至有传闻说是不属于这个次元的。'),
(13452889, 'Vector Scare Archfiend', '矢量恐吓恶魔', 'ベクター・スケア・デーモン', 'Link Monster', 'Cyberse', 'DARK', NULL, 2400, NULL, '电子界族怪兽2只以上 ①：这张卡战斗破坏对方怪兽送去墓地时，把这张卡所连接区1只自己怪兽解放才能发动。破坏的那只怪兽在作为这张卡所连接区的自己·对方场上特殊召唤。这个效果在对方场上把怪兽特殊召唤的场合，这次战斗阶段中，这张卡只再1次可以攻击。'),
(27015862, 'Veda Kalanta', '韦陀・迦罗达', 'ヴェーダ＝カーランタ', 'Effect Monster', 'Warrior', 'DARK', 8, 2500, 2100, '这个卡名的①②的效果1回合各能使用1次。 ①：场上的卡被效果破坏的场合，若场上有「维萨斯-斯塔弗罗斯特」存在则能发动。这张卡从手卡特殊召唤。那之后，可以从自己的卡组·墓地把1张「新世坏」加入手卡。 ②：这张卡以外的自己怪兽被效果破坏的场合，以对方场上1只怪兽为对象才能发动。那只怪兽破坏，这张卡的攻击力直到回合结束时上升那个原本攻击力数值。'),
(40785230, 'Veda Kalarcanum', '韦陀・优婆尼沙昙', 'ヴェーダ＝ウパニシャッド', 'Pendulum Effect Monster', 'Warrior', 'DARK', 12, NULL, 4000, '这张卡不能通常召唤，用这张卡的灵摆效果才能特殊召唤。自己对「吠陀-优婆尼沙昙」1回合只能有1次特殊召唤。 ①：1回合1次，对方从额外卡组把怪兽特殊召唤的场合，从自己的手卡·场上·墓地把12张卡里侧除外才能发动。变成这个回合的结束阶段。 ②：自己准备阶段发动。这张卡回到手卡。那之后，可以把自己的手卡·卡组·墓地·除外状态的1只「吠陀」怪兽特殊召唤。'),
(23299957, 'Vehicroid Connection Zone', '交通机人连接区', 'ビークロイド・コネクション・ゾーン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从自己的手卡·场上把「交通机人」融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。这个效果特殊召唤的怪兽不会被效果破坏，那只怪兽的效果不会被无效化。'),
(8540986, 'Veidos the Dragon of Endless Darkness', '灭亡之暗 维都苏', '滅亡き闇 ヴェイドス', 'Fusion Monster', 'Pyro', 'DARK', 10, 3000, 1700, '「灭亡龙 威多释」＋9星以下的炎族怪兽2只以上 这个卡名的③的效果1回合只能使用1次。 ①：这张卡融合召唤的场合才能发动。对方场上的魔法·陷阱卡全部破坏。 ②：只要这张卡在怪兽区域存在，这张卡不会被效果破坏，对方不能把这张卡作为怪兽的效果的对象。 ③：对方把场上的魔法·陷阱·怪兽的效果发动时，把自己场上1张表侧表示的「灰灭」卡送去墓地才能发动。那张卡破坏。'),
(78783557, 'Veidos the Eruption Dragon of Extinction', '灭亡龙 维都苏', '滅亡龍 ヴェイドス', 'Effect Monster', 'Pyro', 'DARK', 9, 2800, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合，自己·对方的主要阶段，以场地区域1张卡为对象才能发动。这张卡在对方场上特殊召唤，作为对象的卡破坏。那之后，可以从卡组选1张「灰灭」永续陷阱卡加入手卡或在自己场上盖放。 ②：这张卡从对方场上送去墓地的场合才能发动。场上的怪兽全部破坏。'),
(90434926, 'Veil of Darkness', '漆黑之帐', '漆黒のトバリ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己的抽卡阶段抽到的卡是暗属性怪兽的场合，可以把那张卡给对方观看，那张卡送去墓地。那之后，可以从自己卡组抽1张卡。'),
(613013, 'Veiss Shark', '白煞鲨', 'バイス・シャーク', 'Effect Monster', 'Fish', 'WATER', 4, 1800, 1100, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤的场合，把自己场上1只鱼族怪兽解放才能发动。从卡组把1只鱼族「鲨」怪兽特殊召唤。这个回合，自己不是水属性怪兽不能特殊召唤。 ②：持有这张卡作为素材中的「鲨龙兽」超量怪兽得到以下效果。 ●1回合1次，魔法·陷阱卡的效果发动时，把这张卡2个超量素材取除才能发动。那个效果无效并破坏。'),
(70491682, 'Vendread Anima', '仇尸・阿尼玛', 'ヴェンデット・アニマ', 'Effect Monster', 'Zombie', 'DARK', 1, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把墓地的这张卡除外，以「复仇死者·阿尼玛」以外的除外的1只自己的「复仇死者」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是不死族怪兽不能特殊召唤。 ②：使用场上的这张卡仪式召唤的「复仇死者」怪兽得到以下效果。 ●这张卡战斗破坏的怪兽不去墓地而除外。'),
(3909436, 'Vendread Battlelord', '仇尸・骸骨战将', 'ヴェンデット・バスタード', 'Ritual Effect Monster', 'Zombie', 'DARK', 7, 2700, NULL, '「复仇死者」仪式魔法卡降临。这个卡名的①②的效果1回合各能使用1次。 ①：从自己墓地把1张「复仇死者」卡除外，宣言卡的种类（怪兽·魔法·陷阱）才能发动。这个回合，对方不能把宣言的种类的卡的效果发动。 ②：仪式召唤的这张卡被送去墓地的场合才能发动。从卡组把1只仪式怪兽加入手卡，从卡组把1只「复仇死者」怪兽送去墓地。'),
(76798740, 'Vendread Charge', '仇尸・突击', 'ヴェンデット・チャージ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从手卡以及自己场上的表侧表示怪兽之中把1只不死族怪兽送去墓地才能发动。从卡组把1只「复仇死者」怪兽特殊召唤。'),
(13482075, 'Vendread Chimera', '仇尸・客迈拉', 'ヴェンデット・キマイラ', 'Ritual Effect Monster', 'Zombie', 'DARK', 5, 2300, NULL, '「复仇死者」仪式魔法卡降临。这个卡名的①②的效果1回合各能使用1次。 ①：要让场上的卡破坏的魔法·陷阱·怪兽的效果发动时，从自己墓地把1只不死族怪兽除外才能发动。那个发动无效并破坏。 ②：这张卡为仪式召唤而被解放或者除外的场合发动。对方场上的全部怪兽的攻击力·守备力下降500。'),
(49394035, 'Vendread Core', '仇尸・核心', 'ヴェンデット・コア', 'Effect Monster', 'Zombie', 'DARK', 1, NULL, 500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在墓地存在的场合，从自己墓地把这张卡以外的1只不死族怪兽除外才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：使用场上的这张卡仪式召唤的「复仇死者」怪兽得到以下效果。 ●这张卡不会成为对方的效果的对象。'),
(60375194, 'Vendread Daybreak', '仇尸・破晓', 'ヴェンデット・デイブレイク', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：对方场上的卡数量比自己场上的卡多的场合才能发动。选自己场上1只仪式召唤的「复仇死者」怪兽，那只怪兽以外的场上的卡全部破坏。那只「复仇死者」怪兽只要在场上表侧表示存在不能直接攻击。'),
(67267333, 'Vendread Houndhorde', '仇尸・地狱猎犬', 'ヴェンデット・ヘルハウンド', 'Effect Monster', 'Zombie', 'DARK', 3, NULL, 2100, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在墓地存在的场合，从手卡丢弃1张「复仇死者」卡才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：使用场上的这张卡仪式召唤的「复仇死者」怪兽得到以下效果。 ●1回合1次，以对方场上1张魔法·陷阱卡为对象才能发动。那张卡除外。这个效果在对方回合也能发动。'),
(33971095, 'Vendread Nightmare', '仇尸・梦魇', 'ヴェンデット・ナイトメア', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，从自己的手卡·场上把「复仇死者」怪兽任意数量解放，以自己场上1只表侧表示怪兽为对象才能发动。那只怪兽的等级直到回合结束时上升解放的怪兽数量的数值。 ②：自己的「复仇死者」仪式怪兽的攻击破坏对方怪兽时才能发动。那只自己怪兽的攻击力上升1000。'),
(76871889, 'Vendread Nights', '仇尸・厄夜', 'ヴェンデット・ナイト', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己主要阶段丢弃1张手卡才能发动。从卡组把1只「复仇死者」怪兽加入手卡。 ②：自己的「复仇死者」怪兽的攻击破坏对方怪兽时，从自己墓地把1只「复仇死者」怪兽除外才能发动。那只怪兽向对方怪兽可以继续攻击。'),
(30650147, 'Vendread Reorigin', '仇尸・复生', 'ヴェンデット・リボーン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽解放，把持有和那个原本等级相同等级的1只「复仇死者衍生物」（不死族·暗·攻/守0）在自己场上特殊召唤。只要这个效果特殊召唤的衍生物在怪兽区域存在，自己不是「复仇死者」怪兽不能召唤·特殊召唤。'),
(2266498, 'Vendread Reunion', '仇尸・复合', 'ヴェンデット・リユニオン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把仪式召唤的手卡1只「复仇死者」仪式怪兽给对方观看。等级合计直到变成和给人观看的仪式怪兽的等级相同为止，选除外的自己的「复仇死者」怪兽任意数量里侧守备表示特殊召唤（同名卡最多1张）。那之后，那些里侧守备表示怪兽全部解放从手卡把那只仪式怪兽仪式召唤。'),
(31772684, 'Vendread Revenants', '仇尸・归来者', 'ヴェンデット・レヴナント', 'Effect Monster', 'Zombie', 'DARK', 4, 1800, 200, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡被对方破坏送去墓地的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：使用场上的这张卡仪式召唤的「复仇死者」怪兽得到以下效果。 ●1回合1次，以对方场上1只特殊召唤的怪兽为对象才能发动。那只怪兽除外。这个效果在对方回合也能发动。'),
(2287848, 'Vendread Revolution', '仇尸・复醒', 'ヴェンデット・リバース', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：丢弃1张手卡，以自己墓地1只「复仇死者」怪兽和1张仪式魔法卡为对象才能发动。那只怪兽守备表示特殊召唤，那张仪式魔法卡加入手卡。 ②：把墓地的这张卡除外，以除外的5只自己的不死族怪兽为对象才能发动。那些怪兽加入卡组洗切。那之后，自己从卡组抽1张。'),
(29348048, 'Vendread Scavenger', '仇尸・殇痕食腐者', 'ヴェンデット・スカヴェンジャー', 'Ritual Effect Monster', 'Zombie', 'DARK', 8, 2800, NULL, '「复仇死者」仪式魔法卡降临。这个卡名的①②的效果1回合各能使用1次。 ①：双方的主要阶段，把自己场上1只不死族怪兽解放才能发动。这张卡的攻击力直到回合结束时上升解放的怪兽的原本攻击力数值。 ②：这张卡在墓地存在，自己场上有「归魂复仇死者·屠魔侠」存在的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(49477180, 'Vendread Striges', '仇尸・吸血鸟', 'ヴェンデット・ストリゲス', 'Effect Monster', 'Zombie', 'DARK', 2, 500, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡被送去墓地的场合，把手卡1张「复仇死者」卡给对方观看才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：使用场上的这张卡仪式召唤的「复仇死者」怪兽得到以下效果。 ●这张卡和对方怪兽进行战斗的伤害计算后才能发动。自己从卡组抽1张，那之后选1张手卡丢弃。'),
(95220856, 'Vengeful Bog Spirit', '怨灵的湿地带', '怨霊の湿地帯', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '全场怪兽召唤·反转召唤·特殊召唤的那个回合不能攻击。'),
(21702241, 'Vengeful Servant', '反目的从者', '反目の従者', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备怪兽的控制权转移时，给与装备怪兽的控制者装备怪兽的原本攻击力数值的伤害。'),
(26046205, 'Vengeful Shinobi', '恶忍', '悪シノビ', 'Effect Monster', 'Warrior', 'DARK', 2, 400, 800, '场上表侧攻击表示存在的这张卡被选择作为攻击对象时，从自己卡组抽1张卡。'),
(66100116, 'Vengeful Witch', '暴紫罗女巫', 'バイオレンス・ウィッチ', 'Effect Monster', 'Plant', 'DARK', 4, 1100, 1200, '这个卡名的①②的效果1回合各能使用1次。 ①：「黑蔷薇龙」或者有那个卡名记述的怪兽或植物族同调怪兽在自己场上存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡被送去墓地的场合，若场上有同调怪兽存在，丢弃1张手卡才能发动。从卡组把1只守备力1500以下的植物族怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是同调怪兽不能从额外卡组特殊召唤。'),
(8062132, 'Vennominaga the Deity of Poisonous Snakes', '毒蛇神 维诺米纳迦', '毒蛇神ヴェノミナーガ', 'Effect Monster', 'Reptile', 'DARK', 10, NULL, NULL, '这张卡不能通常召唤。「蛇神降临」的效果以及这张卡的效果才能特殊召唤。这张卡的攻击力上升自己墓地的爬虫类族怪兽数量×500的数值。这张卡只要在场上表侧表示存在，不会成为这张卡以外的卡的效果的对象，也不受效果影响。这张卡被战斗破坏送去墓地时，可以通过把这张卡以外的自己墓地1只爬虫类族怪兽从游戏中除外，这张卡特殊召唤。这张卡给与对方基本分战斗伤害时，给这张卡放置1个超毒指示物。这张卡有3个超毒指示物放置时，这张卡的控制者决斗胜利。'),
(72677437, 'Vennominon the King of Poisonous Snakes', '毒蛇王 维诺米隆', '毒蛇王ヴェノミノン', 'Effect Monster', 'Reptile', 'DARK', 8, NULL, NULL, '这张卡不能用这张卡以外的效果怪兽的效果特殊召唤。这张卡的攻击力上升自己墓地的爬虫类族怪兽数量×500的数值。这张卡只要在场上表侧表示存在，不受「蛇毒沼泽」的效果影响。这张卡被战斗破坏送去墓地时，可以通过把这张卡以外的自己墓地1只爬虫类族怪兽从游戏中除外，这张卡特殊召唤。'),
(10441498, 'Vennu, Bright Bird of Divinity', '辉神鸟 贝努鸟', '輝神鳥ヴェーヌ', 'Ritual Effect Monster', 'Fairy', 'LIGHT', 8, 2800, 2000, '「原初的叫唤」降临。 ①：1回合1次，把手卡1只怪兽给对方观看，以场上1只表侧表示怪兽为对象才能发动。这个回合，作为对象的怪兽的等级变成和给人观看的怪兽相同。 ②：1回合1次，这张卡以外的自己的手卡·场上的怪兽被解放的场合，以自己墓地1只怪兽为对象才能发动。那只怪兽加入手卡。'),
(9284723, 'Venom Boa', '蛇毒巨蟒', 'ヴェノム・ボア', 'Effect Monster', 'Reptile', 'EARTH', 5, 1600, 1200, '1回合只有1次，可以给对方场上1只怪兽放置2个毒指示物。这个效果使用的回合这只怪兽不能攻击宣言。'),
(4466015, 'Venom Burn', '蛇毒飞溅', 'ヴェノム・スプラッシュ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择1只放置有毒指示物的怪兽发动。把那张卡的毒指示物取除，给与对方基本分取除的毒指示物数量×700的数值的伤害。'),
(22499463, 'Venom Cobra', '蛇毒眼镜蛇', 'ヴェノム・コブラ', 'Normal Monster', 'Reptile', 'EARTH', 4, 100, 2000, '被坚硬鳞片覆盖全身的巨大眼镜蛇，能射出大量的毒液攻击，但因为体型的巨大，毒液并无任何特别之处。'),
(36278828, 'Venom Serpent', '蛇毒魔双蛇', 'ヴェノム・サーペント', 'Effect Monster', 'Reptile', 'DARK', 4, 1000, 800, '1回合只有1次，可以给对方场上1只怪兽放置1个毒指示物。'),
(60728397, 'Venom Shot', '蛇毒喷射', 'ヴェノム・ショット', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有「毒蛇王 维诺米隆」「毒蛇神 维诺米纳迦」或者名字带有「蛇毒」的怪兽表侧表示存在时才能发动。从自己卡组把1只爬虫类族怪兽送去墓地，给对方场上表侧表示存在的1只怪兽放置2个毒指示物。'),
(73899015, 'Venom Snake', '蛇毒响尾蛇', 'ヴェノム・スネーク', 'Effect Monster', 'Reptile', 'EARTH', 3, 1200, 600, '1回合只有1次，可以给对方场上1只怪兽放置1个毒指示物。这个效果使用的回合这只怪兽不能攻击宣言。'),
(54306223, 'Venom Swamp', '蛇毒沼泽', 'ヴェノム・スワンプ', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '每次双方回合的结束阶段，给场上表侧表示存在的名字带有「蛇毒」的怪兽以外的表侧表示存在的全部怪兽放置1个毒指示物。每有1个毒指示物，攻击力下降500。被这个效果把攻击力变成0的怪兽破坏。'),
(93298460, 'Ventdra, the Empowered Warrior', '魔装战士 风龙', '魔装戦士 ヴァンドラ', 'Effect Monster', 'Warrior', 'WIND', 5, 2000, 800, '①：这张卡可以直接攻击。 ②：这张卡从场上送去墓地的场合，以自己墓地1只龙族·战士族·魔法师族的通常怪兽为对象才能发动。那只怪兽加入手卡。'),
(55125728, 'Vera the Vernusylph Goddess', '春化精的女神 薇拉', '春化精の女神 ヴェーラ', 'Effect Monster', 'Fairy', 'EARTH', 8, 2400, 3000, '这个卡名的①②的效果1回合各能使用1次。 ①：以对方场上1只表侧表示怪兽为对象才能发动。得到那只怪兽的控制权。这个效果得到控制权的怪兽变成地属性。 ②：对方回合，以自己墓地1只地属性怪兽为对象才能发动。那只怪兽特殊召唤。 ③：1回合1次，对方发动的怪兽的效果处理时，自己场上有地属性怪兽5只以上存在的场合，可以把那个发动的效果无效并破坏。'),
(80402389, 'Verdant Sanctuary', '大树海', '大樹海', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '场上表侧表示存在的昆虫族怪兽被战斗或者卡的效果破坏送去墓地时，那些怪兽的控制者可以把和破坏的怪兽相同等级的1只昆虫族怪兽从卡组加入手卡。'),
(59576447, 'Verdict of Anubis', '阿努比斯的审判', 'アヌビスの審判', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有其他的魔法·陷阱卡3张以上存在，对方把魔法·陷阱卡发动时才能发动。那个发动无效并破坏。自己场上有「王家的神殿」存在的场合，可以再把对方场上的怪兽全部破坏。那个场合，再给与对方破坏的怪兽的原本攻击力合计数值一半的伤害。'),
(66698383, 'Vermillion Dragon Mech', '灼银之机龙', '灼銀の機竜', 'Synchro Monster', 'Machine', 'FIRE', 9, 2700, 1800, '调整＋调整以外的怪兽1只以上 ①：1回合1次，从自己的手卡·墓地以及自己场上的表侧表示怪兽之中把1只调整除外，以场上1张卡为对象才能发动。那张卡破坏。 ②：同调召唤的这张卡被效果破坏送去墓地的场合，以除外的1只自己的调整为对象才能发动。那只怪兽加入手卡。'),
(35752363, 'Vermillion Sparrow', '朱雀', '朱雀', 'Fusion Monster', 'Pyro', 'FIRE', 5, 1900, 1500, '「赤剑之莱蒙多斯」＋「炎之魔神」'),
(37313338, 'Vernusylph and the Changing Season', '春化精的历替', '春化精の暦替', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己墓地1只「春化精」怪兽为对象才能发动。那只怪兽加入手卡或特殊召唤。 ②：自己手卡是0张的场合，对方回合，把墓地的这张卡除外才能发动。从自己墓地把「春化精」怪兽尽可能特殊召唤（同名卡最多1张）。这个效果特殊召唤的怪兽在自己结束阶段回到持有者手卡。这个效果在这张卡送去墓地的回合不能发动。'),
(63708033, 'Vernusylph and the Flower Buds', '春化精与花蕾', '春化精と花蕾', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以最多有从墓地特殊召唤的自己场上的地属性怪兽种类数量的对方场上的表侧表示的卡为对象才能发动。选作为对象的卡数量的自己场上的地属性怪兽回到持有者手卡，作为对象的卡回到持有者手卡。'),
(14108995, 'Vernusylph Corolla', '春化精的花冠', '春化精の花冠', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，自己场上的地属性怪兽也当作「春化精」怪兽使用。 ②：1回合1次，自己为让手卡的「春化精」怪兽的效果发动而把那只怪兽和1张卡从手卡丢弃的场合，可以作为代替只把那只怪兽丢弃。'),
(7206349, 'Vernusylph in Full Bloom', '春化精的花盛', '春化精の花盛', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：只要自己场上有地属性怪兽5只以上存在，自己场上的怪兽的攻击力上升1000。 ②：从自己的手卡·墓地把1张「春化精与花蕾」除外才能发动。从卡组把1只「春化精的女神 春」特殊召唤。 ③：从自己墓地有「春化精」怪兽特殊召唤的场合，以自己或者对方的场上·墓地1只怪兽为对象才能发动。那只怪兽回到持有者手卡。'),
(36745317, 'Vernusylph of the Awakening Forests', '森与觉醒的春化精', '森と目覚の春化精', 'Effect Monster', 'Fairy', 'EARTH', 4, 900, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡和1只怪兽或者和1张「春化精」卡从手卡丢弃才能发动。把1只可以通常召唤的地属性怪兽从卡组送去墓地。那之后，可以从自己墓地选和那只怪兽卡名不同的1只地属性怪兽特殊召唤。这个回合，自己不能把地属性以外的怪兽的效果发动。 ②：以自己场上1只「春化精」怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时变成2倍。'),
(9350312, 'Vernusylph of the Flourishing Hills', '丘与萌芽的春化精', '丘と芽吹の春化精', 'Effect Monster', 'Fairy', 'EARTH', 4, 200, 2000, '这个卡名的①的效果1回合只能使用1次。 ①：把这张卡和1只怪兽或者和1张「春化精」卡从手卡丢弃才能发动。从卡组把「丘与发芽的春化精」以外的1张「春化精」卡加入手卡。那之后，可以从自己墓地选1只地属性怪兽特殊召唤。这个回合，自己不能把地属性以外的怪兽的效果发动。 ②：只要这张卡在怪兽区域存在，自己场上的「春化精」怪兽不会被效果破坏。'),
(62133026, 'Vernusylph of the Flowering Fields', '花与原野的春化精', '花と野原の春化精', 'Effect Monster', 'Fairy', 'EARTH', 3, 600, 1600, '这个卡名的①的效果1回合只能使用1次。 ①：把这张卡和1只怪兽或者和1张「春化精」卡从手卡丢弃才能发动。从自己墓地选「花与原野的春化精」以外的1只地属性怪兽加入手卡。那之后，可以从自己墓地选1只地属性怪兽特殊召唤。这个回合，自己不能把地属性以外的怪兽的效果发动。 ②：只要这张卡在怪兽区域存在，自己场上的「春化精」怪兽不会成为对方的效果的对象。'),
(81519836, 'Vernusylph of the Misting Seedlings', '苗与霞的春化精', '苗と霞の春化精', 'Effect Monster', 'Fairy', 'EARTH', 3, 400, 800, '这个卡名的①的效果1回合只能使用1次。 ①：把这张卡和1只怪兽或和1张「春化精」卡从手卡丢弃才能发动。从卡组把「苗与霞的春化精」以外的1只天使族·地属性怪兽加入手卡。那之后，可以从自己墓地把1只地属性怪兽特殊召唤。这个回合，自己不能把地属性以外的怪兽的效果发动。 ②：只要这张卡在怪兽区域存在，「春化精」怪兽以外的场上的怪兽的攻击力下降600。'),
(9238125, 'Vernusylph of the Thawing Mountains', '山与融雪的春化精', '山と雪解の春化精', 'Effect Monster', 'Fairy', 'EARTH', 3, 1100, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡和1只怪兽或者和1张「春化精」卡从手卡丢弃才能发动。自己从卡组抽1张。那之后，可以从自己墓地选1只地属性怪兽特殊召唤。这个回合，自己不能把地属性以外的怪兽的效果发动。 ②：以自己场上1只「春化精」怪兽为对象才能发动。这个回合，那只怪兽在同1次的战斗阶段中可以作2次攻击。'),
(73664385, 'Verre Magic - Lacrima of Light', '结晶魔术 光之泪', '結晶魔術 光の涙', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「大贤者」卡、「魔女术」卡使用。 ①：可以从以下效果选择1个发动（这个卡名的以下效果1回合各能选择1次）。 ●自己场上有「大贤者」怪兽或「魔女术」怪兽存在的场合才能发动。从卡组把1只魔法师族怪兽或1张魔法卡送去墓地。 ●对方把效果发动时才能发动。从手卡·卡组把1只「大贤者」怪兽或「魔女术」怪兽特殊召唤。'),
(22623509, 'Verre, the Maid of Endymion', '恩底弥翁的侍女 薇儿', 'エンディミオンの侍女ヴェール', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 500, 1400, '这个卡名在规则上也当作「魔女术」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：魔法卡的效果发动的回合的自己主要阶段才能发动。这张卡从手卡特殊召唤。 ②：这张卡特殊召唤的场合才能发动。从卡组把1张「魔女术」魔法·陷阱卡或「次元魔法」加入手卡。 ③：只要自己的场上或墓地有「圣月之皇太子 雷古勒斯」存在，这张卡的攻击力上升2300。'),
(50259460, 'Versago the Destroyer', '破坏神 瓦沙克', '破壊神 ヴァサーゴ', 'Effect Monster', 'Fiend', 'DARK', 3, 1100, 900, '这张卡可以代替融合怪兽素材的其中1只来融合。这个时候，其他的融合素材必须是指定的融合素材。'),
(904185, 'Vertical Landing', '垂直着陆', '垂直着陸', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '把衍生物以外的自己场上的风属性怪兽任意数量解放才能发动。解放的怪兽数量的「幻兽机衍生物」（机械族·风·3星·攻/守0）在自己场上特殊召唤。「垂直着陆」在1回合只能发动1张。'),
(97345699, 'Vesper Girsu', '宵星的闪光', '宵星の閃光', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：对方场上的怪兽数量比自己场上的怪兽多2只以上的场合才能发动。对方可以把自身场上的怪兽任意数量送去墓地。自己让对方场上的怪兽数量的以下效果适用。 ●0只：自己基本分变成一半。 ●1只：对方回复2000基本分。 ●2只：对方手卡全部直到结束阶段表侧除外。 ●3只以上：这个回合，对方不能把怪兽的效果发动。'),
(65124425, 'Vessel for the Dragon Cycle', '虚空龙轮', '虚ろなる龍輪', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把1只幻龙族怪兽送去墓地。自己场上有效果怪兽以外的表侧表示怪兽存在的场合，可以再把和送去墓地的那只怪兽卡名不同的1只「天威」怪兽从卡组加入手卡。'),
(10642488, 'Vic Viper T301', 'V型蛇 T301', 'ビック・バイパー T３０１', 'Effect Monster', 'Machine', 'LIGHT', 4, 1200, 800, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在，自己的表侧表示怪兽和对方怪兽进行战斗的攻击宣言时才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：只要这张卡在怪兽区域存在，自己场上的其他的机械族·光属性怪兽的攻击力上升1200。'),
(78910832, 'Vic Viper Type-L', 'V型蛇 Type－L', 'ビック・バイパー Type－L', 'Effect Monster', 'Machine', 'LIGHT', 4, 1200, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：自己战斗阶段开始时，可以从以下效果选择1个发动。 ●从手卡把1只机械族怪兽特殊召唤。 ●从卡组把1只4星以下的机械族·光属性怪兽送去墓地。 ②：这张卡被破坏的场合，以自己墓地1只机械族·光属性怪兽为对象才能发动。那只怪兽特殊召唤。这个效果把原本攻击力是1200以下的怪兽特殊召唤的场合，那个攻击力上升1200。'),
(43014054, 'Vice Berserker', '恶狂战士', 'バイス・バーサーカー', 'Effect Monster', 'Fiend', 'DARK', 4, 1000, 1000, '这张卡作为同调召唤的素材送去墓地的场合，给与那个玩家2000分伤害。此外，这张卡为同调素材的同调怪兽的攻击力直到这个回合的结束阶段时上升2000。'),
(54343893, 'Vice Dragon', '恶龙', 'バイス・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 5, 2000, 2400, '①：只有对方场上才有怪兽存在的场合，这张卡可以从手卡特殊召唤。这个方法特殊召唤的这张卡的原本的攻击力·守备力变成一半。'),
(65815684, 'Vicious Astraloud', '维刹思・阿斯特劳德', 'ヴィシャス＝アストラウド', 'Fusion Monster', 'Fairy', 'DARK', 8, 3000, 3000, '「维萨斯-斯塔弗罗斯特」＋攻击力1500/守备力2100的怪兽 把自己的场上·墓地的上记卡除外的场合才能特殊召唤。 ①：这张卡特殊召唤成功的场合，以这张卡以外的场上1只怪兽为对象才能发动。那只怪兽破坏，这张卡的攻击力上升那个原本攻击力和原本守备力之内较高方数值的一半。 ②：这张卡不会被战斗破坏。'),
(75524092, 'Vicious Claw', '堕恶之爪', 'ヴィシャス・クロー', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备怪兽的攻击力上升300。装备怪兽被战斗破坏的场合，作为代替让这张卡回到手卡。再把进行战斗的对方怪兽以外的1只怪兽破坏，给与对方基本分600分伤害。那之后，在对方场上把1只「邪心衍生物」（恶魔族·暗·7星·攻/守2500）特殊召唤。这张卡回到手卡的回合「堕恶之爪」不能从手卡使用。'),
(75162696, 'Victoria', '维多利亚', 'ウィクトーリア', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1800, 1500, '1回合1次，可以把对方墓地存在的1只龙族怪兽在自己场上特殊召唤。只要这张卡在场上表侧表示存在，对方不能选择表侧表示存在的其他的天使族怪兽作为攻击对象。'),
(79928401, 'Victorica, Angel of Bravery', '勇气之天使 维多利卡', '勇気の天使ヴィクトリカ', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1400, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合才能发动。从手卡把1只5星以上的光属性怪兽特殊召唤，自己失去那只怪兽的原本攻击力数值的基本分。这个效果特殊召唤的怪兽的攻击力直到回合结束时变成2倍。 ②：怪兽区域的这张卡被破坏的场合，从自己墓地把这张卡以外的1只天使族怪兽除外才能发动。和除外的怪兽等级相同的1只天使族怪兽从卡组加入手卡。'),
(44910027, 'Victory Dragon', '胜利龙', 'ヴィクトリー・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 8, 2400, 3000, '这张卡不能特殊召唤。只能用自己场上3只龙族怪兽作为祭品进行祭品召唤出场。这张卡直接攻击对方造成对方基本分为0的时候，这张卡的主人得到比赛的胜利。'),
(300302075, 'Victory of the Shadow Riders', NULL, NULL, 'Skill Card', 'Kagemaru', NULL, NULL, NULL, NULL, NULL),
(93130021, 'Victory Viper XX03', '胜利蛇XX03', 'ビクトリー・バイパー XX０３', 'Effect Monster', 'Machine', 'LIGHT', 4, 1200, 1000, '①：这张卡战斗破坏对方怪兽的场合，从以下效果选择1个发动。 ●这张卡的攻击力上升400。 ●以场上1张表侧表示的魔法·陷阱卡为对象发动。那张表侧表示卡破坏。 ●把持有一直和这张卡相同种族·属性·等级·攻击力·守备力的1只「子机衍生物」在自己场上特殊召唤。这张卡变成不在怪兽区域表侧表示存在时这衍生物破坏。'),
(70488851, 'Vidrium the Power Patron of Chaos Extermination', NULL, NULL, 'Pendulum Effect Monster', 'Fairy', 'DARK', 12, 5000, NULL, NULL),
(15610297, 'Vijam the Cubic Seed', '方界胤 毗贾姆', '方界胤ヴィジャム', 'Effect Monster', 'Fiend', 'DARK', 1, NULL, NULL, '①：这张卡不会被战斗破坏。 ②：这张卡和对方怪兽进行战斗的伤害步骤结束时才能发动。怪兽区域的这张卡当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置，给那只对方怪兽放置1个方界指示物。有方界指示物放置的怪兽不能攻击，效果无效化。 ③：这张卡的效果让这张卡当作永续魔法卡使用的场合，自己主要阶段才能发动。魔法与陷阱区域的这张卡特殊召唤。'),
(39774685, 'Vile Germs', '魔菌', '魔菌', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '植物族才能装备。1只装备怪兽的攻击力·守备力上升300。'),
(73219648, 'Vilepawn Archfiend', '地狱兵卒恶魔', 'ヘルポーンデーモン', 'Effect Monster', 'Fiend', 'EARTH', 2, 1200, 200, '这张卡的控制者在自己的每1个准备阶段支付500基本分。当这张卡成为对方所控制的卡的效果对象时，在效果处理时掷1次骰子，若掷出3，则使此效果无效并将其破坏。只要这张卡在场上存在，除这张卡的同名卡以外，对方不能攻击自己场上名称中含有「恶魔」字样的怪兽。'),
(73483491, 'Vindikite R-Genex', '真次代机・风隼', 'レアル・ジェネクス・ヴィンディカイト', 'Synchro Monster', 'Machine', 'WIND', 8, 2400, 1000, '「次世代」调整＋调整以外的风属性怪兽1只以上 ①：对方怪兽不能选择这张卡作为攻击对象。 ②：这张卡战斗破坏对方怪兽时才能发动。从卡组把1只「次世代」怪兽加入手卡。'),
(75493362, 'Vingolf''s Blessing', '梵格尔夫的祝福', 'ヴィンゴルヴの祝福', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的③的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只天使族·光属性怪兽送去墓地。 ②：自己场上的天使族怪兽的攻击力上升自己的场上·墓地的天使族怪兽数量×100。 ③：这张卡被送去墓地的场合，以自己墓地1只4星以下的天使族怪兽为对象才能发动。那只怪兽特殊召唤。'),
(94042337, 'Violent Rain', '暴雨怪', 'スコール', 'Normal Monster', 'Aqua', 'WATER', 4, 1550, 800, '突然降下倾盆大雨的怪兽。'),
(15052462, 'Violet Crystal', '紫水晶', '紫水晶', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '不死族才能装备。1只装备怪兽的攻击力和守备力上升300。'),
(62379337, 'Violet Witch', '堇菜之魔女', 'バイオレット・ウィッチ', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1100, 1200, '这张卡被战斗破坏送去墓地时，从自己卡组把1只守备力1500以下的植物族怪兽加入手卡。'),
(1683982, 'Viper''s Grudge', '毒蛇的怨念', '毒蛇の怨念', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：只要这张卡在魔法与陷阱区域存在，爬虫类族以外的自己怪兽不能攻击，不能把效果发动。 ②：自己场上的表侧表示的爬虫类族怪兽被战斗破坏的场合或者被送去墓地的场合才能发动。从卡组把1只4星以下的爬虫类族怪兽特殊召唤。 ③：魔法与陷阱区域的这张卡被破坏的场合才能发动。除外的自己的爬虫类族怪兽全部回到墓地。'),
(64973456, 'Viper''s Rebirth', '毒蛇苏生', 'ヴァイパー・リボーン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己墓地的怪兽只有爬虫类族怪兽的场合，以调整以外的自己墓地1只怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合的结束阶段破坏。'),
(300102005, 'Viral Infection', NULL, NULL, 'Skill Card', 'Kaiba', NULL, NULL, NULL, NULL, NULL),
(601193, 'Virgil, Rock Star of the Burning Abyss', '彼岸诗人 维吉乌斯', '彼岸の詩人 ウェルギリウス', 'Synchro Monster', 'Spellcaster', 'LIGHT', 6, 2500, 1000, '调整＋调整以外的怪兽1只以上 「彼岸的诗人 维吉尔」的③的效果1回合只能使用1次。 ①：「彼岸的诗人 维吉尔」在自己场上只能有1只表侧表示存在。 ②：1回合1次，从手卡丢弃1张「彼岸」卡，以对方的场上·墓地1张卡为对象才能发动。那张卡回到持有者卡组。 ③：场上的这张卡被战斗·效果破坏送去墓地的场合才能发动。自己从卡组抽1张。'),
(35252119, 'Virtual World Beast - Jiujiu', '电脑堺兽－鹫鹫', '電脳堺獣－鷲々', 'Synchro Monster', 'Psychic', 'WIND', 6, 2400, 1700, '调整＋调整以外的怪兽1只以上 这个卡名的②的效果1回合只能使用1次。 ①：只要原本的种族·属性相同而卡名不同的怪兽在自己墓地有2只以上存在，场上的这张卡不会被战斗·效果破坏。 ②：把原本的种族·属性相同而卡名不同的2只怪兽从自己墓地除外，以场上1张卡为对象才能发动。那张卡送去墓地。'),
(14886190, 'Virtual World City - Kauwloon', '电脑堺都－九龙', '電脳堺都－九竜', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把1张「电脑堺门」卡在自己的魔法与陷阱区域表侧表示放置。那之后，自己场上的「电脑堺门」卡数量的以下效果各能适用。 ●2张以上：这个回合，自己场上的「电脑堺」怪兽的攻击力上升200。 ●3张以上：从自己卡组上面把3张卡送去墓地。 ●4张：从额外卡组把最多4只「电脑堺」怪兽特殊召唤（同名卡最多1张）。'),
(61641818, 'Virtual World Dragon - Longlong', '电脑堺蛟－龙龙', '電脳堺龍－龍々', 'XYZ Monster', 'Wyrm', 'EARTH', 3, 2400, 2000, '相同种族·属性的3星怪兽×2只以上 这个卡名的②的效果1回合只能使用1次。 ①：持有超量素材的这张卡不会成为对方的效果的对象。 ②：对方场上有表侧表示怪兽存在，对方把不在自身场上存在的属性的怪兽的效果发动时，把这张卡2个超量素材取除才能发动。那个发动无效。'),
(13364097, 'Virtual World Gate - Chuche', '电脑堺门－朱雀', '電脳堺門－朱雀', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以场上1张表侧表示的卡为对象才能发动。选除外的2张自己的「电脑堺」卡回到卡组（同名卡最多1张）。那之后，作为对象的卡破坏。 ②：自己主要阶段把墓地的这张卡除外，以自己场上1只「电脑堺」怪兽为对象才能发动。那只怪兽的等级或者阶级直到回合结束时上升或者下降3。'),
(50275295, 'Virtual World Gate - Qinglong', '电脑堺门－青龙', '電脳堺門－青龍', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己墓地把1张「电脑堺」卡除外，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。 ②：把墓地的这张卡除外才能发动。从卡组把1只「电脑堺」怪兽加入手卡。那之后选1张手卡送去墓地。'),
(18249921, 'Virtual World Gate - Xuanwu', '电脑堺门－玄武', '電脳堺門－玄武', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有其他的「电脑堺门」卡存在的场合，自己·对方的战斗阶段，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的表示形式变更。 ②：自己主要阶段把墓地的这张卡除外，以自己墓地1只「电脑堺」怪兽为对象才能发动。那只怪兽效果无效特殊召唤。那之后，选1张手卡送去墓地。'),
(8736823, 'Virtual World Hime - Nyannyan', '电脑堺姬－娘娘', '電脳堺姫－娘々', 'Effect Monster', 'Psychic', 'WIND', 3, 1500, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在墓地存在，自己场上有3星怪兽召唤·特殊召唤的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡当作调整使用，从场上离开的场合除外。这个回合，自己若非等级或者阶级是3以上的怪兽则不能特殊召唤。 ②：这张卡被除外的场合，以这张卡以外的除外的1张自己的卡为对象才能发动。那张卡回到卡组。'),
(49966326, 'Virtual World Kirin - Lili', '电脑堺麒－麟麟', '電脳堺麟－麟々', 'Effect Monster', 'Wyrm', 'EARTH', 6, 1800, 600, '这个卡名的效果1回合只能使用1次。 ①：这张卡在手卡存在的场合，以自己场上1张「电脑堺」卡为对象才能发动。和那张卡种类（怪兽·魔法·陷阱）不同的1张「电脑堺」卡从卡组送去墓地，这张卡特殊召唤。那之后，可以把和作为对象的卡以及送去墓地的卡种类不同的1张「电脑堺麟-麟麟」以外的「电脑堺」卡从卡组送去墓地。这个回合，自己若非等级或者阶级是3以上的怪兽则不能特殊召唤。'),
(92519087, 'Virtual World Kyubi - Shenshen', '电脑堺狐－仙仙', '電脳堺狐－仙々', 'Synchro Monster', 'Psychic', 'WIND', 9, 2800, 2400, '调整＋调整以外的怪兽1只以上 这个卡名的②③的效果1回合各能使用1次。 ①：从场上送去墓地的卡不去墓地而除外。 ②：自己怪兽的攻击宣言时才能发动。选除外的1只自己或者对方的怪兽回到墓地。 ③：把这张卡以外的2只原本的种族·属性不同的怪兽从自己墓地除外才能发动。这张卡从墓地特殊召唤。这个效果在这张卡送去墓地的回合不能发动。'),
(49088914, 'Virtual World Mai-Hime - Lulu', '电脑堺媛－瑞瑞', '電脳堺媛－瑞々', 'Tuner Monster', 'Psychic', 'WIND', 3, 1600, 600, '这个卡名的效果1回合只能使用1次。 ①：这张卡在手卡存在的场合，以自己场上1张「电脑堺」卡为对象才能发动。和那张卡种类（怪兽·魔法·陷阱）不同的1张「电脑堺」卡从卡组送去墓地，这张卡特殊召唤。那之后，可以把和作为对象的卡以及送去墓地的卡种类不同的1张「电脑堺媛-瑞瑞」以外的「电脑堺」卡从卡组加入手卡。这个回合，自己若非等级或者阶级是3以上的怪兽则不能特殊召唤。'),
(20799347, 'Virtual World Oto-Hime - Toutou', '电脑堺嫦－兔兔', '電脳堺嫦－兎々', 'Effect Monster', 'Wyrm', 'EARTH', 6, 1200, 1800, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上的怪兽不存在的场合或者只有念动力族·幻龙族怪兽的场合，这张卡可以不用解放作召唤。 ②：这张卡在墓地存在的场合，从手卡丢弃1只念动力族·幻龙族怪兽才能发动。这张卡当作调整使用特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。这个回合，自己若非等级或者阶级是3以上的怪兽则不能特殊召唤。'),
(27069566, 'Virtual World Phoenix - Fanfan', '电脑堺凤－凰凰', '電脳堺凰－凰々', 'XYZ Monster', 'Wyrm', 'EARTH', 6, 2600, 2000, '6星怪兽×2只以上 这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，把这张卡2个超量素材取除，以对方场上1张表侧表示的卡和自己或者对方的墓地1张卡为对象才能发动。那些卡除外。 ②：超量召唤的这张卡被对方怪兽的攻击或者对方的效果破坏的场合才能发动。把2只种族·属性相同的「电脑堺」怪兽从卡组特殊召唤。'),
(86483512, 'Virtual World Roshi - Laolao', '电脑堺悟－老老', '電脳堺悟－老々', 'Tuner Monster', 'Psychic', 'WIND', 6, NULL, 2400, '这个卡名的效果1回合只能使用1次。 ①：这张卡在手卡存在的场合，以自己场上1张「电脑堺」卡为对象才能发动。和那张卡种类（怪兽·魔法·陷阱）不同的1张「电脑堺」卡从卡组送去墓地，这张卡特殊召唤。那之后，可以从自己墓地选和送去墓地的卡卡名不同的1只「电脑堺」怪兽效果无效守备表示特殊召唤。这个回合，自己若非等级或者阶级是3以上的怪兽则不能特殊召唤。'),
(90664857, 'Virtual World Shell - Jaja', '电脑堺玄－甲甲', '電脳堺甲－甲々', 'XYZ Monster', 'Wyrm', 'EARTH', 3, 1000, 2400, '3星怪兽×2只以上 ①：1回合1次，把这张卡1个超量素材取除，以自己场上1只表侧表示怪兽为对象才能发动。那只怪兽直到对方回合结束时不会被战斗破坏。 ②：1回合1次，原本的种族·属性相同的怪兽在自己墓地有2只以上存在，这张卡和对方怪兽进行战斗的伤害计算后才能发动。那只对方怪兽除外。'),
(95243515, 'Virtual World Tiger - Fufu', '电脑堺彪－虎虎', '電脳堺虎－虎々', 'XYZ Monster', 'Wyrm', 'EARTH', 9, 2600, 2800, '9星怪兽×2只以上 ①：这张卡得到自己场上的「电脑堺门」卡数量的以下效果。 ●2张以上：这张卡可以直接攻击。 ●4张：这张卡不受「电脑堺」卡以外的卡发动的效果影响。 ②：1回合1次，把这张卡1个超量素材取除，以自己场上1只效果怪兽和与那只怪兽是种族和属性不同的场上1只效果怪兽为对象才能发动。那些怪兽的效果直到回合结束时无效。这个效果在对方回合也能发动。'),
(12571621, 'Virtual World Xiezhi - Jiji', '电脑堺獬－豸豸', '電脳堺豸－豸々', 'Effect Monster', 'Wyrm', 'EARTH', 3, 1000, 1600, '这个卡名的效果1回合只能使用1次。 ①：这张卡在手卡存在的场合，以自己场上1张「电脑堺」卡为对象才能发动。和那张卡种类（怪兽·魔法·陷阱）不同的1张「电脑堺」卡从卡组送去墓地，这张卡特殊召唤。这个回合的结束阶段，可以从自己墓地选「电脑堺豸-豸豸」以外的1只「电脑堺」怪兽加入手卡。这个回合，自己若非等级或者阶级是3以上的怪兽则不能特殊召唤。'),
(80534031, 'Virtue Stream', '善德风暴', 'ヴァーチュ・ストリーム', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只鱼族·海龙族·水族怪兽和对方场上2张卡为对象才能发动。那些卡破坏。 ②：把墓地的这张卡除外，以场上1只表侧表示怪兽为对象才能发动。那只怪兽是水属性的场合，这个回合，作为对象的怪兽只有1次不会被效果破坏。那以外的场合，作为对象的怪兽变成水属性。'),
(54591086, 'Virus Cannon', '魔法除去细菌兵器', '魔法除去細菌兵器', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把衍生物以外的自己场上的怪兽任意数量解放才能发动。对方从卡组选解放的怪兽数量的魔法卡送去墓地。'),
(821049, 'Visas Amritara', '维萨思・阿弥利都罗', 'ヴィサス＝アムリターラ', 'Synchro Tuner Monster', 'Warrior', 'LIGHT', 8, 2500, 2100, '调整1只以上＋光属性怪兽1只 这个卡名的②③的效果1回合各能使用1次。 ①：这张卡只要在怪兽区域存在，卡名当作「维萨斯-斯塔弗罗斯特」使用。 ②：这张卡同调召唤的场合才能发动。从卡组把有「维萨斯-斯塔弗罗斯特」的卡名记述的1张魔法·陷阱卡加入手卡。 ③：自己主要阶段才能发动。自己场上1只怪兽破坏。这个回合中自己场上的同调怪兽的攻击力上升800。'),
(14391625, 'Visas Samsara', '维萨思・轮回转生', 'ヴィサス＝サンサーラ', 'Tuner Monster', 'Fairy', 'LIGHT', 4, 1500, 2100, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡的卡名只要在场上·墓地存在当作「维萨斯-斯塔弗罗斯特」使用。 ②：以自己的场上·墓地·除外状态的「维萨斯」怪兽任意数量为对象才能发动。那些「维萨斯」怪兽回到卡组，这张卡从手卡特殊召唤。这张卡的攻击力上升这个效果回去的种类×400。 ③：把自己场上的这张卡作为同调素材的场合，可以把这张卡当作调整以外的怪兽使用。'),
(56099748, 'Visas Starfrost', '维萨思・史塔弗罗斯特', 'ヴィサス＝スタフロスト', 'Tuner Monster', 'Warrior', 'LIGHT', 6, 2100, 1500, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡在手卡存在的场合，以与这张卡是种族和属性不同的自己场上1只怪兽为对象才能发动。那只怪兽破坏，这张卡特殊召唤。 ②：这张卡战斗破坏对方怪兽时才能发动。这张卡的攻击力上升那只怪兽的原本攻击力和原本守备力之内较高方数值的一半。'),
(56043447, 'Viser Des', '万力魔神 死亡拷问机', '万力魔神バイサー・デス', 'Effect Monster', 'Fiend', 'DARK', 4, 500, 1200, NULL),
(78556320, 'Vishwar Randi', '女夜魔战士', 'ヴィシュワ・ランディー', 'Normal Monster', 'Warrior', 'DARK', 3, 900, 700, '侍奉黑暗的女战士。将对方进行血祭是她生存的意义。'),
(57425061, 'Vision Fusion', '幻影融合', '幻影融合', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己的手卡·场上把「英雄」融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。自己的魔法与陷阱区域有融合素材怪兽当作永续陷阱卡使用而存在的场合，也能把那怪兽卡除外作为融合素材（最多2张）。'),
(45170821, 'Vision HERO Adoration', '幻影－英雄 崇高', 'V・HERO アドレイション', 'Fusion Monster', 'Warrior', 'DARK', 8, 2800, 2100, '「英雄」怪兽×2 ①：1回合1次，以对方场上1只表侧表示怪兽和这张卡以外的自己场上1只「英雄」怪兽为对象才能发动。那只对方怪兽的攻击力·守备力直到回合结束时下降那只自己怪兽的攻击力数值。'),
(18094166, 'Vision HERO Faris', '幻影－英雄 法利斯', 'V・HERO ファリス', 'Effect Monster', 'Warrior', 'DARK', 5, 1600, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡丢弃1只其他的「英雄」怪兽才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把「幻影英雄 独善人」以外的1只「幻影英雄」怪兽当作永续陷阱卡使用在自己的魔法与陷阱区域表侧表示放置。这个效果的发动后，直到回合结束时自己不是「英雄」怪兽不能从额外卡组特殊召唤。'),
(54185227, 'Vision HERO Gravito', '幻影－英雄 引力', 'V・HERO グラビート', 'Effect Monster', 'Warrior', 'DARK', 4, 500, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合，以除外的1只自己的「英雄」怪兽为对象才能发动。那只怪兽加入手卡。 ②：把这张卡解放，以自己的魔法与陷阱区域2张「幻影英雄」怪兽卡为对象才能发动。那些卡特殊召唤。'),
(22865492, 'Vision HERO Increase', '幻影－英雄 增量', 'V・HERO インクリース', 'Effect Monster', 'Warrior', 'DARK', 3, 900, 1100, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己因战斗·效果受到伤害的场合才能发动。墓地的这张卡当作永续陷阱卡使用在自己的魔法与陷阱区域表侧表示放置。 ②：这张卡是当作永续陷阱卡使用的场合，自己·对方的主要阶段，把自己场上1只「英雄」怪兽解放才能发动。这张卡特殊召唤。 ③：这张卡从魔法与陷阱区域特殊召唤的场合才能发动。从卡组把1只4星以下的「幻影英雄」怪兽特殊召唤。'),
(61320914, 'Vision HERO Minimum Ray', '幻影－英雄 微射线', 'V・HERO ミニマム・レイ', 'Effect Monster', 'Warrior', 'DARK', 3, 1200, 700, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己因战斗·效果受到伤害的场合才能发动。墓地的这张卡当作永续陷阱卡使用在自己的魔法与陷阱区域表侧表示放置。 ②：这张卡是当作永续陷阱卡使用的场合，双方的主要阶段，把自己场上1只「英雄」怪兽解放才能发动。这张卡特殊召唤。 ③：这张卡从魔法与陷阱区域的特殊召唤成功的场合才能发动。选对方场上1只4星以下的怪兽破坏。'),
(96693371, 'Vision HERO Multiply Guy', '幻影－英雄 倍增魔侠', 'V・HERO マルティプリ・ガイ', 'Effect Monster', 'Warrior', 'DARK', 3, 800, 700, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己因战斗·效果受到伤害的场合才能发动。墓地的这张卡当作永续陷阱卡使用在自己的魔法与陷阱区域表侧表示放置。 ②：这张卡是当作永续陷阱卡使用的场合，双方的主要阶段，把自己场上1只「英雄」怪兽解放才能发动。这张卡特殊召唤。 ③：这张卡从魔法与陷阱区域的特殊召唤成功的场合才能发动。选场上1只怪兽，那个攻击力上升800。');